// ah.nl rendert de bonuspagina client-side; daarom gebruiken we een server-gerenderde
// aggregatorpagina en laten we Gemini de aanbiedingen uit de kale tekst halen.
let html = String($input.first().json.data || '');
html = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
let tekst = html
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&euro;/gi, '€')
  .replace(/\s+/g, ' ')
  .trim();
if (tekst.length < 500) {
  throw new Error('De AH-aanbiedingenpagina leverde te weinig tekst op — structuur gewijzigd of verzoek geblokkeerd.');
}
return [{ json: { tekst: tekst.slice(0, 60000) } }];

