const uit = $input.first().json.output || $input.first().json;
const lijst = (uit.aanbiedingen || []).filter(a => a && a.product);
if (!lijst.length) {
  throw new Error('Geen Plus-aanbiedingen kunnen extraheren uit de pagina.');
}
const vandaag = new Date().toISOString().slice(0, 10);
const offers = lijst.map(a => ({
  winkel: 'Plus',
  product: String(a.product).trim(),
  prijs: String(a.prijs || '').trim(),
  korting: String(a.korting || '').trim(),
  geldig_tot: String(a.geldig_tot || '').trim(),
  opgehaald_op: vandaag,
}));
return [{ json: { winkel: 'Plus', aantal: offers.length, aanbiedingen: offers } }];

const inst = $('Instellingen aanbiedingen').first().json;
const chatId = String(inst.chatId || '').trim();
if (!chatId) { return []; } // geen chat-id ingesteld → stil eindigen

function veiligJson(naam) {
  try { return $(naam).first().json; } catch (e) { return null; }
}
function veiligRijen(naam) {
  try {
    const rijen = $(naam).all().map(i => i.json);
    // Een leesnode die 'doorgaan bij fout' heeft, geeft bij een storing één item met .error
    if (rijen.length && rijen[0] && rijen[0].error != null) { return null; }
    return rijen;
  } catch (e) { return null; }
}

const ah = veiligJson('AH normaliseren');
const plus = veiligJson('Plus normaliseren');
const offers = [
  ...((ah && ah.aanbiedingen) || []),
  ...((plus && plus.aanbiedingen) || []),
];

// --- Wat zijn 'onze' producten? ------------------------------------------------
// Eerder vergeleken we hele regels ('1 liter halfvolle melk') letterlijk met de
// productnaam van een aanbieding, en telde een item pas mee als het twee keer
// exact zo op de lijst had gestaan. Allebei te streng: bijna geen twee regels zijn
// identiek, en een hele regel komt nooit letterlijk in een productnaam voor.
// Nu vergelijken we losse woorden, met dezelfde bewerking aan beide kanten.

// Woorden die niets zeggen over wát je koopt: hoeveelheden, verpakkingen, reclametaal.
const STOPWOORDEN = new Set([
  'de', 'het', 'een', 'van', 'voor', 'met', 'per', 'aan', 'bij', 'uit', 'ook', 'nog',
  'pak', 'pakje', 'zak', 'zakje', 'fles', 'flesje', 'blik', 'blikje', 'pot', 'potje',
  'bak', 'bakje', 'doos', 'doosje', 'krat', 'rol', 'rollen', 'tros', 'bos', 'bosje',
  'net', 'stuk', 'stuks', 'plak', 'plakken', 'punt', 'set', 'duo', 'multi',
  'gram', 'kilo', 'liter', 'milliliter',
  'grote', 'groot', 'kleine', 'klein', 'verse', 'vers', 'half', 'halve', 'halfvolle',
  'magere', 'mager', 'volle', 'mini', 'maxi', 'jong', 'jonge', 'oud', 'oude',
  'biologisch', 'biologische', 'scharrel',
  'korting', 'gratis', 'actie', 'aanbieding', 'voordeel', 'voordeelpak', 'bonus',
  'familiepak', 'alle', 'alles', 'alleen', 'alternatief', 'soort', 'soorten', 'varianten',
]);

// De stam hoeft taalkundig niet te kloppen: als 'tomaten' aan beide kanten op
// dezelfde 'tomat' uitkomt, matcht het. Daarom bewerken we boodschappen én
// productnamen met precies dezelfde functie.
function stam(woord) {
  if (woord.length > 5 && woord.endsWith('en')) { return woord.slice(0, -2); }
  if (woord.length > 4 && (woord.endsWith('s') || woord.endsWith('e'))) { return woord.slice(0, -1); }
  return woord;
}

function woorden(tekst) {
  return String(tekst || '')
    .toLowerCase()
    .replace(/[^a-zàâäçéèêëîïôöùûü]+/g, ' ') // cijfers en leestekens weg: '1l', '500gr', '2x'
    .split(' ')
    .filter(w => w.length >= 3 && !STOPWOORDEN.has(w));
}

const gewicht = {};   // stam → hoe vaak we hem tegenkwamen
const origineel = {}; // stam → het woord zoals jullie het schrijven, voor in het bericht

function tel(tekst) {
  const gezien = new Set();
  for (const w of woorden(tekst)) {
    const s = stam(w);
    if (gezien.has(s)) { continue; } // 'melk melk' in één regel telt als één
    gezien.add(s);
    gewicht[s] = (gewicht[s] || 0) + 1;
    if (!origineel[s] || w.length < origineel[s].length) { origineel[s] = w; }
  }
}

// Boodschappen: afgevinkte items tellen gewoon mee, dat ís juist de historie.
const lijstRijen = (veiligRijen('Boodschappenhistorie ophalen') || []).filter(r => r && r.tekst);
// Staat er een boodschappenlijst tussen, gebruik dan alleen die — een klusjeslijst
// zegt niets over wat je in de supermarkt koopt.
const boodschappen = lijstRijen.filter(r => String(r.lijst || '').includes('boodschap'));
const bron = boodschappen.length ? boodschappen : lijstRijen;
for (const r of bron) { tel(r.tekst); }

// Gerechten: 'pasta pesto' levert 'pasta' en 'pesto' op.
const maaltijden = (veiligRijen('Maaltijdhistorie ophalen') || []).filter(r => r && r.gerecht);
for (const r of maaltijden) { tel(r.gerecht); }

// --- Aanbiedingen langs de zoektermen leggen -----------------------------------
const termen = Object.keys(gewicht);
const treffers = new Map();

for (const o of offers) {
  const productStammen = woorden(o.product).map(stam);
  let beste = null;
  for (const t of termen) {
    const raak = productStammen.some(ps =>
      ps === t
      // Nederlands plakt woorden aan elkaar: 'scharreleieren' bevat 'eier'.
      || (t.length >= 4 && ps.includes(t))
      // Korte woorden alleen vooraan, zodat 'kip' wel 'kipfilet' vangt maar niet zomaar iets.
      || (t.length === 3 && ps.startsWith(t))
    );
    if (raak && (beste === null || gewicht[t] > gewicht[beste])) { beste = t; }
  }
  if (beste === null) { continue; }
  const sleutel = `${o.winkel}|${o.product}`;
  const bestaand = treffers.get(sleutel);
  if (!bestaand || bestaand.score < gewicht[beste]) {
    treffers.set(sleutel, {
      winkel: o.winkel,
      product: o.product,
      korting: o.korting,
      term: origineel[beste],
      score: gewicht[beste],
    });
  }
}

const gesorteerd = [...treffers.values()].sort(
  (a, b) => b.score - a.score || String(a.product).localeCompare(String(b.product)),
);
const TOON = 15;

// --- Bericht -------------------------------------------------------------------
const delen = [];
delen.push(`🛒 Aanbiedingen opgehaald: ${ah ? ah.aantal + ' van AH' : 'AH mislukt'}, ${plus ? plus.aantal + ' van Plus' : 'Plus mislukt'}.`);

if (gesorteerd.length) {
  const regels = gesorteerd.slice(0, TOON).map(
    t => `• [${t.winkel}] ${t.product}${t.korting ? ' — ' + t.korting : ''}  (${t.term})`,
  );
  if (gesorteerd.length > TOON) {
    regels.push(`…en nog ${gesorteerd.length - TOON} andere.`);
  }
  delen.push(`\nDit past bij wat jullie kopen en koken:\n${regels.join('\n')}`);
} else if (!bron.length && !maaltijden.length) {
  delen.push('\nIk kan nog niet zien wat jullie vaak kopen: er staat nog niets op de boodschappenlijst en er zijn nog geen maaltijden gelogd.');
} else {
  delen.push('\nNiets uit jullie boodschappen of gerechten is deze week in de aanbieding.');
}

delen.push(`\n_Gekeken naar ${bron.length} ${bron.length === 1 ? 'lijstitem' : 'lijstitems'} en ${maaltijden.length} ${maaltijden.length === 1 ? 'gerecht' : 'gerechten'}._`);
delen.push('Vraag me gerust: "is er ... in de aanbieding?" of "wat eten we deze week?"');
return [{ json: { chatId, tekst: delen.join('\n') } }];

const inst = $('Instellingen aanbiedingen').first().json;
const chatId = String(inst.chatId || '').trim();
if (!chatId) { return []; }
const meldingen = $input.all().map(i => {
  const e = i.json.error;
  if (e && typeof e === 'object') { return e.message || JSON.stringify(e); }
  return String(e || i.json.message || 'onbekende fout');
});
return [{ json: { chatId, tekst: `⚠️ Het ophalen van de aanbiedingen is (deels) mislukt:\n${[...new Set(meldingen)].map(m => '• ' + m).join('\n')}\n\nZie de uitvoeringsdetails in n8n.` } }];
